const item = $input.first().json;
let type = 'unknown', chatId = '', telegramId = '', callbackData = '', userName = '';
if (item.callback_query) {
  type = 'callback_query';
  callbackData = item.callback_query.data || '';
  chatId = String(item.callback_query.message.chat.id);
  telegramId = String(item.callback_query.from.id);
  userName = ((item.callback_query.from.first_name || '') + ' ' + (item.callback_query.from.last_name || '')).trim();
} else if (item.message) {
  type = 'message';
  chatId = String(item.message.chat.id);
  telegramId = String(item.message.from.id);
  userName = ((item.message.from.first_name || '') + ' ' + (item.message.from.last_name || '')).trim();
  callbackData = item.message.text || '';
}
return [{ json: { ...item, detected_type: type, chat_id: chatId, telegram_id: telegramId, callback_data: callbackData, user_name: userName } }];

const item = $input.first().json;
// chat_id and callback_data now available directly from merged data
const data = item.callback_data || '';
const chatId = item.chat_id || String(item['Telegram_ID'] || '');

if (data === 'action_history') {
  return [{ json: { ...item, chat_id: chatId, route: 'history' } }];
}

if (!data.startsWith('action_') && !data.startsWith('checkin_') && !data.startsWith('checkout_')) {
  return [{ json: { ...item, chat_id: chatId, route: 'unknown' } }];
}

const now = new Date();
const sg = new Date(now.toLocaleString('en-US', { timeZone: 'Asia/Singapore' }));
const h = sg.getHours(), min = sg.getMinutes();
const shift = (h >= 7 && h < 19) ? 'Day Shift' : 'Night Shift';

let lateMin = 0;
if (h >= 7 && h < 19) {
  if (h > 7 || (h === 7 && min > 0)) lateMin = (h - 7) * 60 + min;
} else {
  if (h >= 19) lateMin = (h - 19) * 60 + min;
  else if (h < 7) lateMin = (h + 5) * 60 + min;
}

const isLate = lateMin > 0;
const status = isLate ? 'Late (' + lateMin + ' min)' : 'On Time';
const sgTime = sg.toLocaleString('en-SG', { timeZone: 'Asia/Singapore' });
const timeStr = String(h).padStart(2,'0') + ':' + String(min).padStart(2,'0');
const days = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
const dd = String(sg.getDate()).padStart(2,'0');
const mm = String(sg.getMonth()+1).padStart(2,'0');
const sgDate = dd+'/'+mm+'/'+sg.getFullYear()+' ('+days[sg.getDay()]+')';

let route = '', action = '', site = '', reply_markup = null;

if (data === 'action_checkin') {
  route = 'show_sites'; action = 'Check In';
  const sites = (item['Assigned Sites'] || 'S01').split(',').map(s => s.trim());
  reply_markup = { inline_keyboard: sites.map(s => [{ text: '\uD83D\uDCCD ' + s, callback_data: 'checkin_' + s }]) };
} else if (data === 'action_checkout') {
  route = 'show_sites'; action = 'Check Out';
  const sites = (item['Assigned Sites'] || 'S01').split(',').map(s => s.trim());
  reply_markup = { inline_keyboard: sites.map(s => [{ text: '\uD83D\uDCCD ' + s, callback_data: 'checkout_' + s }]) };
} else if (data.startsWith('checkin_')) {
  route = 'log'; action = 'Check In'; site = data.replace('checkin_', '');
} else if (data.startsWith('checkout_')) {
  route = 'log'; action = 'Check Out'; site = data.replace('checkout_', '');
}

return [{ json: { ...item, chat_id: chatId, route, action, site, current_shift: shift, is_late: isLate, late_min: lateMin, status, sg_time: sgTime, sg_date: sgDate, sg_time_short: timeStr, reply_markup } }];

const item = $input.first().json;
const now = new Date();
const sg = new Date(now.toLocaleString('en-US', { timeZone: 'Asia/Singapore' }));
const h = sg.getHours(), min = sg.getMinutes();
const shift = (h >= 7 && h < 19) ? 'Day Shift (7AM-7PM)' : 'Night Shift (7PM-7AM)';

let lateMin = 0;
if (h >= 7 && h < 19) {
  if (h > 7 || (h === 7 && min > 0)) lateMin = (h - 7) * 60 + min;
} else {
  if (h >= 19) lateMin = (h - 19) * 60 + min;
  else if (h < 7) lateMin = (h + 5) * 60 + min;
}

const days = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
const dd = String(sg.getDate()).padStart(2,'0');
const mm = String(sg.getMonth()+1).padStart(2,'0');
const sgDate = dd+'/'+mm+'/'+sg.getFullYear()+' ('+days[sg.getDay()]+')';
const timeStr = String(h).padStart(2,'0') + ':' + String(min).padStart(2,'0');
const sgTime = sg.toLocaleString('en-SG', { timeZone: 'Asia/Singapore' });

const chatId = item.chat_id || String(item['Telegram_ID'] || '');

const reply_markup = {
  inline_keyboard: [
    [{ text: '\u2705 Clock In', callback_data: 'action_checkin' }],
    [{ text: '\uD83D\uDEAA Clock Out', callback_data: 'action_checkout' }],
    [{ text: '\uD83D\uDCCB History', callback_data: 'action_history' }]
  ]
};

return [{ json: { ...item, chat_id: chatId, current_shift: shift, is_late: lateMin > 0, late_min: lateMin, sg_time: sgTime, sg_date: sgDate, sg_time_short: timeStr, reply_markup } }];

const all = $input.all();
const last5 = all.slice(-5).reverse();

// Telegram_ID is stored in Attendance rows (added when logging)
const firstRow = all[0]?.json || {};
const chatId = String(firstRow['Telegram_ID'] || firstRow['Telegram ID'] || '');
const guardName = firstRow['Name'] || '';
const staffId = firstRow['Staff ID'] || '';

let text = '\uD83C\uDFE2 <b>GUARDFORCE SERVICES PTE LTD</b>\n';
text += '\uD83D\uDCCB <b>ATTENDANCE HISTORY</b>\n';
text += '\uD83D\uDC64 <b>' + guardName + '</b> | \uD83C\uDFAB ' + staffId + '\n';
text += '\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n';

if (last5.length === 0) {
  text += 'No records found.';
} else {
  last5.forEach((item, i) => {
    const r = item.json;
    const icon = r['Action'] === 'Check In' ? '\u2705' : '\uD83D\uDEAA';
    text += '\n' + (i+1) + '. ' + icon + ' ' + (r['Action'] || '') + '\n';
    text += '   \uD83D\uDCCD ' + (r['Site'] || '') + ' | \u23F0 ' + (r['Shift'] || '') + '\n';
    text += '   \uD83D\uDD50 ' + (r['Timestamp'] || '') + '\n';
    text += '   \uD83D\uDCCA ' + (r['Status'] || '') + '\n';
  });
}

return [{ json: { chat_id: chatId, history_text: text } }];
